// Что часто советуют, но польза не доказана
ND.SUPPORT_UNPROVEN = [
  { t: "Утяжелённые одеяла", note: "доказательств пользы мало, исследования небольшие и противоречивые", src: "Eron et al., 2020, American Journal of Occupational Therapy" },
  { t: "Безглютеновые, безказеиновые и другие исключающие диеты при РАС", note: "NICE не рекомендует их для лечения особенностей РАС", src: "NICE CG142" },
  { t: "Хелирование и другие «лечения аутизма»", note: "NICE прямо не рекомендует, есть риск вреда", src: "NICE CG142" },
  { t: "Компьютерные тренажёры памяти при СДВГ", note: "улучшают натренированную задачу, но не симптомы СДВГ в жизни", src: "Cortese et al., 2015, Journal of the American Academy of Child & Adolescent Psychiatry" },
  { t: "Нейрофидбек при СДВГ", note: "при слепой оценке эффект не подтвердился (данные по детям)", src: "Cortese et al., 2016, Journal of the American Academy of Child & Adolescent Psychiatry" },
];

ND.support = function (E, R) {
  const groups = ND.SUPPORT.filter((g) => g.when(E, R));
  const any = E.asd.level !== "none" || E.adhd.level !== "none" || groups.length > 0;
  return { groups, base: any ? ND.SUPPORT_BASE : [], unproven: any ? ND.SUPPORT_UNPROVEN : [] };
};
